        };

        internal static void Apply(VisualElement root)
        {
            if (root == null) return;

            foreach (var field in root.Query<PropertyField>().ToList())
            {
                var path = field.bindingPath;
                if (string.IsNullOrEmpty(path)) continue;

                if (Tooltips.TryGetValue(path, out var tooltip) && string.IsNullOrEmpty(field.tooltip))
                {
                    field.tooltip = tooltip;
                }

                if (Headers.TryGetValue(path, out var headerText))
                {
                    var parent = field.parent;
                    if (parent == null) continue;

                    int index = parent.IndexOf(field);
                    if (index > 0 && parent[index - 1] is Label existing && existing.text == headerText)
                    {
                        continue;
                    }

                    var headerLabel = new Label(headerText);
                    headerLabel.AddToClassList("section-header");
                    parent.Insert(index, headerLabel);
                }
            }
        }
    }
